import { describe, expect, it } from "vitest";
import {
  compareApiReports,
  diffReports,
  parseReport,
  // @ts-expect-error The scripts are dependency-free JavaScript with JSDoc types.
} from "../../../../scripts/release/apiChanges.mjs";

interface Change {
  kind: string;
  name: string;
  likelyBreaking: boolean;
  detail: string;
}

function report(...blocks: string[]): string {
  return [
    '## API Report File for "@mapcairn/example"',
    "",
    "> Do not edit this file.",
    "",
    "```ts",
    "",
    blocks.join("\n\n"),
    "",
    "// (No @packageDocumentation comment for this package)",
    "",
    "```",
    "",
  ].join("\n");
}

function changes(before: string[], after: string[]): Change[] {
  return diffReports(report(...before), report(...after));
}

const greet = "// @public\nexport function greet(name: string): string;";
const mode = '// @public\nexport type Mode = "light" | "dark";';
const options =
  "// @public\nexport interface Options {\n    label: string;\n    size?: number;\n}";

describe("parseReport", () => {
  it("names each export, including an alias printed with its export line", () => {
    const entries = parseReport(
      report(
        greet,
        "// @public\nconst blur_2: `var(--${string})`;\nexport { blur_2 as blur }",
        "// Warning: (ae-forgotten-export) The symbol needs to be exported\n//\n// @beta\nexport class Store {\n    // (undocumented)\n    open(): void;\n}",
      ),
    );
    expect([...entries.keys()]).toEqual(["greet", "blur", "Store"]);
    expect(entries.get("Store")?.tags).toEqual(["// @beta"]);
    expect(entries.get("Store")?.lines).toEqual([
      "export class Store {",
      "    open(): void;",
      "}",
    ]);
  });

  it("reads nothing from text without a report block", () => {
    expect(parseReport("no report here").size).toBe(0);
  });
});

describe("diffReports", () => {
  it("finds nothing when the reports match", () => {
    expect(changes([greet, mode], [greet, mode])).toEqual([]);
  });

  it("calls a removed export likely breaking", () => {
    expect(changes([greet, mode], [greet])).toEqual([
      expect.objectContaining({
        kind: "removed",
        name: "Mode",
        likelyBreaking: true,
      }),
    ]);
  });

  it("does not call a new export breaking", () => {
    expect(changes([greet], [greet, mode])).toEqual([
      expect.objectContaining({
        kind: "added",
        name: "Mode",
        likelyBreaking: false,
      }),
    ]);
  });

  it("calls a changed or removed line likely breaking", () => {
    const [change] = changes(
      [greet],
      [
        "// @public\nexport function greet(name: string, polite: boolean): string;",
      ],
    );
    expect(change).toMatchObject({ kind: "changed", likelyBreaking: true });
    expect(change.detail).toContain("greet(name: string)");
  });

  it("does not call an added member of an interface breaking", () => {
    const [change] = changes(
      [options],
      [
        options.replace(
          "    size?: number;",
          "    size?: number;\n    colour?: string;",
        ),
      ],
    );
    expect(change).toMatchObject({ kind: "changed", likelyBreaking: false });
  });

  it("calls a removed member of an interface likely breaking", () => {
    const [change] = changes(
      [options],
      [options.replace("    size?: number;\n", "")],
    );
    expect(change).toMatchObject({ kind: "changed", likelyBreaking: true });
  });

  it("calls a new member of an exported union likely breaking, on one line", () => {
    const [change] = changes(
      [mode],
      ['// @public\nexport type Mode = "light" | "dark" | "auto";'],
    );
    expect(change).toMatchObject({
      kind: "union-member-added",
      likelyBreaking: true,
    });
    expect(change.detail).toContain('"auto"');
  });

  it("reads a union that holds bars inside brackets and generics", () => {
    const before =
      "// @public\nexport type Handler = (value: string | number) => void | Promise<void> | Set<string | number>;";
    const after = before.replace(
      "Set<string | number>;",
      "Set<string | number> | null;",
    );
    expect(changes([before], [after])[0]).toMatchObject({
      kind: "union-member-added",
    });
  });

  it("calls a replaced union member a change, not an addition", () => {
    const [change] = changes(
      [mode],
      ['// @public\nexport type Mode = "light" | "night" | "auto";'],
    );
    expect(change).toMatchObject({ kind: "changed", likelyBreaking: true });
  });

  it("calls a new member of an enum likely breaking", () => {
    const before =
      "// @public\nexport enum Level {\n    High = 1,\n    Low = 0\n}";
    const after = before.replace("    Low = 0", "    Low = 0,\n    Mid = 2");
    expect(changes([before], [after])[0]).toMatchObject({
      kind: "enum-member-added",
      likelyBreaking: true,
    });
  });

  it("calls a gained @internal tag likely breaking", () => {
    const [change] = changes([greet], [greet.replace("@public", "@internal")]);
    expect(change).toMatchObject({
      kind: "gained-internal",
      likelyBreaking: true,
    });
  });

  it("notes a gained @beta tag without calling it breaking", () => {
    const [change] = changes([greet], [greet.replace("@public", "@beta")]);
    expect(change).toMatchObject({
      kind: "gained-beta",
      likelyBreaking: false,
    });
  });

  it("ignores comment-only differences", () => {
    expect(changes([greet], [`// (undocumented)\n${greet}`])).toEqual([]);
  });

  it("treats a whole new report as additions and a whole removed one as removals", () => {
    expect(diffReports(null, report(greet))).toEqual([
      expect.objectContaining({ kind: "added", likelyBreaking: false }),
    ]);
    expect(diffReports(report(greet), null)).toEqual([
      expect.objectContaining({ kind: "removed", likelyBreaking: true }),
    ]);
  });

  it("sorts the changes by name", () => {
    const names = changes([], [mode, greet, options]).map(
      (change) => change.name,
    );
    expect(names).toEqual(["greet", "Mode", "Options"]);
  });
});

describe("compareApiReports", () => {
  function source(files: Record<string, string>) {
    return {
      list: (folder: string) =>
        Object.keys(files)
          .filter((file) => file.startsWith(`${folder}/`))
          .map((file) => file.slice(folder.length + 1)),
      read: (file: string) => files[file] ?? null,
    };
  }

  it("compares every package and entry point, and names them", () => {
    const before = source({
      "packages/core/api/index.api.md": report(greet),
      "packages/core/api/contracts.api.md": report(mode),
      "packages/theme/api/index.api.md": report(greet),
    });
    const after = source({
      "packages/core/api/index.api.md": report(greet),
      "packages/core/api/contracts.api.md": report(),
      "packages/theme/api/index.api.md": report(greet, mode),
      "packages/map/api/index.api.md": report(options),
    });
    expect(compareApiReports(before, after)).toEqual([
      expect.objectContaining({
        package: "@mapcairn/core",
        entry: "contracts",
        kind: "removed",
      }),
      expect.objectContaining({
        package: "@mapcairn/theme",
        entry: "index",
        kind: "added",
      }),
      expect.objectContaining({
        package: "@mapcairn/map",
        entry: "index",
        kind: "added",
      }),
    ]);
  });
});
